package net.officefloor.hq.app;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** The audit viewer: reads back what the audit file holds for a sheet; it keeps no record of its own. */
@RestController
@Validated
public class AuditController {

    private final Audit audit;
    private final PersonRepository people;
    private final SheetRepository sheets;

    public AuditController(Audit audit, PersonRepository people, SheetRepository sheets) {
        this.audit = audit;
        this.people = people;
        this.sheets = sheets;
    }

    /** The sheet's audit lines, newest first; with a name, only those about that person, followed by the lines about
     *  them on each of the sheet's descendants (sheets by id, each newest first), then (when the sheet's person of
     *  that name or alias was transferred here) by the lines about them on the sheet they came from. */
    @GetMapping("/api/sheets/{sheetId}/audit")
    public List<String> lines(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestParam(required = false) @Size(max = 200) String name) {
        List<String> lines = new ArrayList<>(audit.lines(sheetId, name));
        if (name != null && !name.isBlank()) {
            sheets.descendantsOf(sheetId).stream().sorted()
                    .forEach(descendant -> lines.addAll(audit.lines(descendant, name)));
            people.findBySheetIdAndNameOrAliasIgnoreCase(sheetId, name.trim())
                    .filter(p -> p.getOriginSheetId() != null)
                    .ifPresent(p -> lines.addAll(audit.lines(p.getOriginSheetId(), p.getName())));
        }
        return lines;
    }
}
import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

// The audit file as it holds a sheet's lines; reading it records nothing.
@Injectable({ providedIn: 'root' })
export class AuditLog {
  private readonly http = inject(HttpClient);

  /** The sheet's audit lines, newest first; with a name, only those about that person. */
  lines(sheetId: string, name: string): Observable<string[]> {
    const params = name.trim() ? new HttpParams().set('name', name) : undefined;
    return this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/audit`, { params });
  }
}
import { Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { AuditLog } from '../../core/audit';
import { Sheets } from '../../core/sheet';

// The audit viewer: the sheet's audit lines exactly as the file holds them, newest first, optionally only those
// about one person.
@Component({
  selector: 'app-audit',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="audit-heading">
      <h3 id="audit-heading">Audit</h3>
      <form [formGroup]="form" (ngSubmit)="show()" aria-label="Show the audit lines">
        <label for="audit-filter">Person (blank: everything)</label>
        <input id="audit-filter" data-testid="audit-filter" formControlName="name" autocomplete="off" />
        <button type="submit" data-testid="audit-show" [disabled]="loading()">Show</button>
        @if (error(); as err) {
          <p role="alert" data-testid="audit-error">{{ err }}</p>
        }
      </form>
      <ol aria-label="Audit lines">
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line }}</li>
        }
      </ol>
    </section>
  `,
})
export class AuditPanel {
  private readonly audit = inject(AuditLog);
  private readonly sheets = inject(Sheets);

  protected readonly lines = signal<string[]>([]);
  protected readonly error = signal<string | null>(null);
  protected readonly loading = signal(false);
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // Another sheet's lines are not left showing once a sheet is (re)loaded.
    toObservable(this.sheets.loaded)
      .pipe(takeUntilDestroyed())
      .subscribe(() => {
        this.lines.set([]);
        this.error.set(null);
      });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  protected show(): void {
    // A second press before the first has answered is ignored.
    if (this.loading()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.loading.set(true);
    this.lines.set([]);
    this.audit.lines(sheet.id, this.form.controls.name.value).subscribe({
      next: (lines) => {
        this.loading.set(false);
        this.lines.set(lines);
      },
      error: () => {
        this.loading.set(false);
        this.error.set('Could not read the audit lines.');
      },
    });
  }
}

